export const Page = (props: PageProps) => {
      const {
  account, rows, items, count, mode, enabled, fallback, selection, data,
  options, key, context, values, prototype, slots,
} = props;
      return (<main>{(() => {
      class Renderer {
        #label = <b>Private label {count}</b>;
        get fallback() { return <p>Class fallback {(async () => { const result = await fetchValue(); return <p>Loaded {result.name}</p>; })()}</p>; }
        render(Value = LocalValue) { return <Value>{this.#label}<section>Method value {(async () => { const result = await fetchValue(); return <p>Loaded {result.name}</p>; })()}</section></Value>; }
        static make() { return <Choice branch={mode} first={(async () => { const result = await fetchValue(); return <p>Loaded {result.name}</p>; })()} other="Static fallback" />; }
      }
      return <Card renderer={new Renderer()} title={Renderer.make()}>{new Renderer().render()}</Card>;
